# Draw lines between points ( Bresenham-like scanline )
def line_scanlines(r1, c1, r2, c2):
    """Scanlines from (r1,c1) to (r2,c2). Returns list of (row, set of cols)"""
    rs = set()

    # Use scanline approach
    # Collect all row indices and their corresponding cols
    if r1 == r2:
        # Horizontal line
        min_c, max_c = min(c1, c2), max(c1, c2)
        for c in range(min_c, max_c + 1):
            rs.add(c)
        return rs

    # Vertical step
    step = 1 if r2 > r1 else -1
    cols = []
    for sr, sc in [(r1, c1), ((r1+r2)//2, (c1+c2)//2), (r2, c2)]:
        cols.append((sc, sr))

    # Actually let me just compute per-row
    for r in range(min(r1, r2), max(r1, r2) + 1):
        if r1 == r2 and r == r1:
            c = c1
        else:
            # Linear interpolation
            t = (r - r1) / abs(r2 - r1)
            c = c1 + t * (c2 - c1)
        rs.add(int(round(c)))

    return rs

